                {
                    if (measurementComplete) FinishPerformance(null);
                    else if (elapsed > 70) throw new InvalidOperationException("No completed rendered Game-camera sampling window.");
                }
                else
                {
                    // Retain diagnostic batch collection, but never qualify it as rendered performance.
                    if (elapsed >= 35) RecordFrame(elapsed, null);
                    if (elapsed >= 50) FinishPerformance(null);
                }
            }
            catch (Exception e)
            {
                if (mode == "performance") FinishPerformance(e.ToString());
